可以将奇数和偶数分别保存到两个 vector 中，并通过结构体返回：
struct OddsAndEvens {
    std::vector<int> odds;
    std::vector<int> evens;
};

OddsAndEvens separateOddsAndEvens(const std::vector<int>& arr) {
    std::vector<int> odds, evens;
    for (int i : arr) {
        if (i % 2 == 1) {
            odds.push_back(i);
        } else {
            evens.push_back(i);
        }
    }
    return { .odds = odds, .evens = evens };
}

调用方式可以写成：
auto result = separateOddsAndEvens(vecUnSplit);
// 使用 result.odds 和 result.evens
